// [Tool] unsubscribe : valider l'action (issue RGPD)
// action = unsubscribe (status -> unsubscribed) ou resubscribe (status -> active)
const input = $input.first().json;
const userId = input.user_id;
const a = String(input.action || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

const UNSUB = ['unsubscribe', 'desabonner', 'desabonnement', 'desinscrire', 'stop'];
const RESUB = ['resubscribe', 'reabonner', 'reabonnement', 'subscribe', 'abonner'];

let status = null;
if (UNSUB.includes(a)) status = 'unsubscribed';
else if (RESUB.includes(a)) status = 'active';

let ok = true;
let message = '';
if (!userId) {
  ok = false;
  message = "Utilisateur non identifié : impossible de modifier l'abonnement.";
} else if (!status) {
  ok = false;
  message = `Action inconnue "${input.action || ''}". Valeurs possibles : unsubscribe (se désabonner) ou resubscribe (se réabonner).`;
}

return [{ json: { ok, message, user_id: userId, status } }];

// [Tool] unsubscribe : réponse { ok, message, data }
const v = $('TOOL - Validate Action').first().json;
if (!v.ok) return [{ json: { ok: false, message: v.message } }];

const row = $input.first().json;
if (!row || !row.status) {
  return [{ json: { ok: false, message: "La mise à jour a échoué : abonnement non modifié." } }];
}

const same = row.previous === row.status;
let message;
if (row.status === 'unsubscribed') {
  message = same
    ? "Tu étais déjà désabonné(e) : aucune newsletter ne t'est envoyée."
    : "Désabonnement effectué : tu ne recevras plus la newsletter. Ton compte et tes réglages sont conservés, tu peux te réabonner quand tu veux.";
} else {
  message = same
    ? "Tu es déjà abonné(e) : la newsletter continue d'être envoyée."
    : "Réabonnement effectué : tu recevras de nouveau ta newsletter avec tes réglages actuels.";
}
return [{ json: { ok: true, message, data: { status: row.status, previous: row.previous } } }];
